INSERT INTO `wpj4_postmeta` VALUES (130,15,'mfn-page-items-seo','Heading\r\n\r\n<h3>Послуги</h3>\r\n\r\ncenter\r\n\r\nhttps://test.med.uz.ua/wp-content/uploads/2017/04/home_oculist_border.png\r\n\r\nno-repeat;center bottom;;\r\n\r\nauto\r\n\r\n0 0 20px\r\n\r\nАвторефрактометрія 2 ока\r\n\r\n150\r\n\r\nгрн.\r\n\r\nright\r\n\r\nbox\r\n\r\nАвтокераторефрактометрія 2 ока\r\n\r\n150\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nВізометрія 2 ока\r\n\r\n100\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nТонометрія за Маклаковим 2 ока\r\n\r\n150\r\n\r\nгрн.\r\n\r\nright\r\n\r\n<ul><li><strong>List</strong> item</li></ul>\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nБіомікроскопія 2 ока\r\n\r\n100\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nБіомікроскопія 1 око\r\n\r\n70\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nОфтальмоскопія ( асферичною лінзою) VOLK-90D/ 78 D 2 ока\r\n\r\n200\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nОфтальмоскопія ( асферичною лінзою) VOLK-90D / 78D 1 око\r\n\r\n150\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nОфтальмоскопія  (дзеркальна)   2 ока\r\n\r\n50\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nОфтальмоскопія  панорамна (PanOptic)   2 ока\r\n\r\n100\r\n\r\nгрн.\r\n\r\nright\r\n\r\n<ul><li><strong>List</strong> item</li></ul>\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nСкіаскопія   2 ока\r\n\r\n100\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nТранспальпебральна тонометрія  2 ока\r\n\r\n40\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nПідбір окулярів   (сферичних)  2 ока\r\n\r\n50\r\n\r\nгрн.\r\n\r\nright\r\n\r\n<ul><li><strong>List</strong> item</li></ul>\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nПідбір окулярів   (сферо-циліндричних)  2 ока\r\n\r\n100\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nПідбір контактних лінз  2 ока\r\n\r\n100\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nВидалення стороннього тіла з поверхневих шарів рогівки та кон\'юктиви  1 око\r\n\r\n200\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nВизначення кута косоокості методом Гіршберга 2 ока\r\n\r\n100\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nПервинна консультація офтальмолога\r\n\r\n350\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nПовторна консультація офтальмолога\r\n\r\n150\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nПервинна консультація дитячого  офтальмолога\r\n\r\n250\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\nПовторна консультація дитячого  офтальмолога\r\n\r\n150\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\n<img src=\"Визначення порушення кольоровідчуття (поліхроматичними таблицями Рабкіна)\" alt=\"\"/>\r\n\r\nВизначення порушення кольоровідчуття (поліхроматичними таблицями Рабкіна)\r\n\r\n120\r\n\r\nгрн.\r\n\r\nright\r\n\r\nicon-target\r\n\r\nbox\r\n\r\n<p><img class=\"alignnone size-medium wp-image-185\" src=\"https://test.med.uz.ua/wp-content/uploads/2018/11/img-20170331-wa0000-225x300.jpg\" alt=\"\" width=\"225\" height=\"300\" /><img class=\"alignnone size-medium wp-image-184\" src=\"https://test.med.uz.ua/wp-content/uploads/2018/11/img-20170324-wa0016-225x300.jpg\" alt=\"\" width=\"225\" height=\"300\" /><img class=\"alignnone size-medium wp-image-183\" src=\"https://test.med.uz.ua/wp-content/uploads/2018/11/img-20170324-wa0014-300x225.jpg\" alt=\"\" width=\"300\" height=\"225\" /><img class=\"alignnone size-medium wp-image-180\" src=\"https://test.med.uz.ua/wp-content/uploads/2018/11/img-20170324-wa0000-277x300.jpg\" alt=\"\" width=\"277\" height=\"300\" /></p>\r\n\r\n');
