INSERT INTO `wpj4_posts` VALUES (758,1,'2021-09-16 17:33:47','2021-09-16 17:33:47','[vc_row][vc_column width=\"1/2\"][vc_column_text]<a href=\"https://test.med.uz.ua/wp-content/uploads/2021/09/yzobrazhenye_viber_2021-09-06_22-43-52-355.jpg\"><img class=\"alignnone wp-image-710 size-large\" src=\"https://test.med.uz.ua/wp-content/uploads/2021/09/yzobrazhenye_viber_2021-09-06_22-43-52-355-918x1024.jpg\" alt=\"\" width=\"918\" height=\"1024\" /></a>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]<span style=\"color: #000000;\"><strong><span style=\"font-size: 18pt; font-family: tahoma, arial, helvetica, sans-serif;\">Крафчик Вікторія Антонівна -косметолог.</span></strong></span>\r\n\r\n<span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">У 2019 році закінчила Ужгородський національний університет.</span>\r\n<span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">Навчалась в Beauty School Isabelle Dupont,яку закінчила у 2020 році.</span>\r\n\r\n<span style=\"font-size: 18pt; color: #000000;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Виконую такі процедури :</span></strong></span>\r\n\r\n<span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">•чистки обличчя;</span>\r\n<span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">•масаж обличчя;</span>\r\n<span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">•пілінги;</span>\r\n<span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">•підбір домашнього догляду.</span>\r\n\r\n<span style=\"color: #000000;\"><em><span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif;\">Все вказане виконується лише на професійній космецевтиці.</span></em></span>\r\n<span style=\"color: #000000;\"><em><span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif;\">Обожнюю робити людей красивими,здоровими та щасливими🌸</span></em></span>[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"400\" title=\"Ультразвукова чистка\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"450\" title=\"Механічна чистка\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"500\" title=\"Комбінована\"][/pricing_item][/vc_column][/vc_row][vc_row][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"600\" title=\"Чистка + пілінг\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"400\" title=\"Карбоксітерапія\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"450\" title=\"Мигдальний пілінг\"][/pricing_item][/vc_column][/vc_row][vc_row][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"450\" title=\"Молочний пілінг\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"350\" title=\"Масаж обличчя+альгінатна маска\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"450\" title=\"Масаж обличчя + золота маска від dr.Kadir\"][/pricing_item][/vc_column][/vc_row][vc_row][vc_column width=\"1/3\"][vc_empty_space][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"1500\" title=\"prx t 33\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][vc_empty_space][/vc_column][/vc_row][vc_row][vc_column][vc_empty_space][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_column_text]<a href=\"https://test.med.uz.ua/wp-content/uploads/2021/09/yzobrazhenye_viber_2021-09-06_22-43-01-958.jpg\"><img class=\"alignnone wp-image-716 size-large\" src=\"https://test.med.uz.ua/wp-content/uploads/2021/09/yzobrazhenye_viber_2021-09-06_22-43-01-958-1024x739.jpg\" alt=\"\" width=\"1024\" height=\"739\" /></a>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]<strong><span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">Бережне очищення,тонізація,холодне розпарювання,заспокійлива маска після очищення.Зволоження та регенерація,все виконується професійною космецевтикою брендів:</span></strong>\r\n<strong><span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">Histomer,Christina,Dr.Kadir,Massena,Holly land,Mesopeel.</span></strong>\r\n<strong><span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">Також до кожної процедури даруємо масаж обличчя по типу шкіри.</span></strong>[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]<strong><span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">Проводимо знижки на глибоке очищення,яке перетвориться в приємний б‘юті-ритуал для твоєї шкіри.</span></strong>\r\n<strong><span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">Чистка шкіри зі знижкою :</span></strong>[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_empty_space][/vc_column][/vc_row][vc_row][vc_column width=\"1/4\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"350\" title=\"Ультразвукова\"][/pricing_item][/vc_column][vc_column width=\"1/4\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"400\" title=\"Механічна\"][/pricing_item][/vc_column][vc_column width=\"1/4\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"450\" title=\"Комбінована\"][/pricing_item][/vc_column][vc_column width=\"1/4\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"550\" title=\"Чистка з пілінгом\"][/pricing_item][/vc_column][/vc_row][vc_row][vc_column][vc_empty_space][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_column_text]<span style=\"font-size: 14pt; color: #000000;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">❗️Акція ❗️- Відновлення шкіри обличчя після спекотного літа</span></strong></span>\r\n\r\n<span style=\"font-size: 14pt; color: #000000;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">350 грн = чистка шкіри обличчя + масаж обличчя</span></strong></span>\r\n\r\n<span style=\"font-size: 14pt; color: #000000;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">При проведенні ЧИСТКИ шкіри обличчя ( ультразвукової / механічної / комбінованої ) отримуєте +подарунок🎁 - МАСАЖ ОБЛИЧЧЯ !!!</span></strong></span>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]<span style=\"font-size: 14pt; color: #000000;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Використовується професійна космецевтика світових лідерів-брендів:</span></strong></span>\r\n<span style=\"font-size: 14pt; color: #000000;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Histomer,Christina,Dr.Kadir,Massena,Holly land,Mesopeel,Mesoestetic.</span></strong></span>\r\n\r\n<span style=\"font-size: 14pt; color: #000000;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Б’юті ритуал проводить для вас професійний косметолог - Крафчик Вікторія</span></strong></span>\r\n\r\n<span style=\"font-size: 14pt; color: #000000;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Чистка шкіри обличчя зі знижкою на вибір :</span></strong></span>[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_empty_space][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<p style=\"text-align: center;\"><span style=\"font-size: 14pt; color: #000000;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Чистка шкіри обличчя включає:</span></strong></span>\r\n<span style=\"font-size: 14pt; color: #000000;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">✔️бережне очищення</span></strong></span>\r\n<span style=\"font-size: 14pt; color: #000000;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">✔️тонізація</span></strong></span>\r\n<span style=\"font-size: 14pt; color: #000000;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">✔️холодне розпарювання</span></strong></span>\r\n<span style=\"font-size: 14pt; color: #000000;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">✔️заспокійлива маска</span></strong></span></p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_empty_space][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"350\" title=\"Ультразвукова\"][/pricing_item][vc_column_text]\r\n<p style=\"text-align: center;\"><span style=\"font-size: 14pt; color: #ff0000;\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"> + масаж обличчя у подарунок 🎁</span></span></p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/2\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"1500\" title=\"Механічна\"][/pricing_item][vc_column_text]\r\n<p style=\"text-align: center;\"><span style=\"font-size: 14pt; color: #ff0000;\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">+ масаж обличчя у подарунок 🎁</span></span></p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"450\" title=\"Комбинирована\"][/pricing_item][vc_column_text]\r\n<p style=\"text-align: center;\"><span style=\"color: #ff0000;\"><span style=\"font-size: 14pt;\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\"><span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif;\">+ масаж обличчя у подарунок 🎁</span></span></span></span></p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/2\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"550\" title=\"Чистка з пілінгом\"][/pricing_item][vc_column_text]\r\n<p style=\"text-align: center;\"><span style=\"font-size: 14pt; color: #ff0000;\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">+ масаж обличчя у подарунок 🎁</span></span></p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_empty_space][/vc_column][/vc_row]','Косметолог','','inherit','closed','closed','','709-revision-v1','','','2021-09-16 17:33:47','2021-09-16 17:33:47','',709,'https://test.med.uz.ua/?p=758',0,'revision','',0);
