INSERT INTO `wpj4_posts` VALUES (851,1,'2021-10-22 06:50:54','2021-10-22 06:50:54','[vc_row][vc_column width=\"1/2\" css=\".vc_custom_1634885393954{margin-top: 30px !important;}\"][vc_column_text]<img class=\"alignnone size-full wp-image-833\" src=\"https://test.med.uz.ua/wp-content/uploads/2021/10/yzobrazhenye_viber_2021-10-21_11-10-39-745.jpg\" alt=\"\" width=\"1350\" height=\"1800\" />[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_empty_space][vc_column_text]<span style=\"font-size: 18pt;\"><span style=\"color: #000080;\"><strong>Мезотерапія</strong></span> <span style=\"color: #000080;\">- це методика введення коктейлів із препаратів у поверхневі та середні шари шкіри . </span></span>\r\n<span style=\"font-size: 18pt; color: #000080;\">Коктейлі можуть містити гіалуронову кислоту, амінокислоти, вітаміни, мікроелементи, пептиди, олігоелементи, ліполітики.</span>[/vc_column_text][vc_empty_space][vc_btn][vc_empty_space][vc_column_text]\r\n<p style=\"text-align: left;\"><span style=\"color: #000080;\"><strong><span style=\"font-size: 18pt; font-family: georgia, palatino, serif;\">Показання:</span></strong></span>\r\n<span style=\"color: #000080;\"><strong><span style=\"font-size: 18pt; font-family: georgia, palatino, serif;\">-надмірна сухість шкіри</span></strong></span>\r\n<span style=\"color: #000080;\"><strong><span style=\"font-size: 18pt; font-family: georgia, palatino, serif;\">-млявість шкіри</span></strong></span>\r\n<span style=\"color: #000080;\"><strong><span style=\"font-size: 18pt; font-family: georgia, palatino, serif;\">-знижений тонус</span></strong></span>\r\n<span style=\"color: #000080;\"><strong><span style=\"font-size: 18pt; font-family: georgia, palatino, serif;\">-дрібні зморшки </span></strong></span>\r\n<span style=\"color: #000080;\"><strong><span style=\"font-size: 18pt; font-family: georgia, palatino, serif;\">-ознаки фотостаріння</span></strong></span>\r\n<span style=\"color: #000080;\"><strong><span style=\"font-size: 18pt; font-family: georgia, palatino, serif;\">-пігментні плями</span></strong></span></p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_empty_space][vc_column_text]\r\n<p style=\"text-align: center;\"><span style=\"font-size: 24pt; color: #000080;\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Акціі</span></span></p>\r\n[/vc_column_text][vc_empty_space][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_column_text]<span style=\"font-size: 14pt; color: #ff0000;\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">❗️Акція ❗️</span></span>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]<span style=\"font-size: 14pt; color: #ff0000;\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">❗️Акція ❗️</span></span>[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_empty_space][vc_column_text]\r\n<p style=\"text-align: center;\"><span style=\"font-size: 24pt; color: #000080;\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Цині</span></span></p>\r\n[/vc_column_text][vc_empty_space][/vc_column][/vc_row][vc_row][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"400\" title=\"Ультразвукова чистка\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"450\" title=\"Механічна чистка\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"500\" title=\"Комбінована\"][/pricing_item][/vc_column][/vc_row][vc_row][vc_column][vc_empty_space][vc_column_text]\r\n<p style=\"text-align: center;\"><span style=\"font-size: 24pt; color: #000080;\"><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Переваги</span></span></p>\r\n[/vc_column_text][vc_empty_space][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_column_text]<img class=\"alignnone wp-imag