INSERT INTO `wpj4_posts` VALUES (888,1,'2021-10-22 08:35:27','2021-10-22 08:35:27','[vc_row][vc_column width=\"1/2\"][vc_column_text]<a href=\"https://test.med.uz.ua/wp-content/uploads/2021/09/yzobrazhenye_viber_2021-09-06_22-43-52-355.jpg\"><img class=\"alignnone wp-image-710 size-large\" src=\"https://test.med.uz.ua/wp-content/uploads/2021/09/yzobrazhenye_viber_2021-09-06_22-43-52-355-918x1024.jpg\" alt=\"\" width=\"918\" height=\"1024\" /></a>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]<span style=\"color: #000000;\"><strong><span style=\"font-size: 18pt; font-family: tahoma, arial, helvetica, sans-serif;\">Крафчик Вікторія Антонівна -косметолог.</span></strong></span>\r\n\r\n<span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">У 2019 році закінчила Ужгородський національний університет.</span>\r\n<span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">Навчалась в Beauty School Isabelle Dupont,яку закінчила у 2020 році.</span>\r\n\r\n<span style=\"font-size: 18pt; color: #000000;\"><strong><span style=\"font-family: tahoma, arial, helvetica, sans-serif;\">Виконую такі процедури :</span></strong></span>\r\n\r\n<span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">•чистки обличчя;</span>\r\n<span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">•масаж обличчя;</span>\r\n<span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">•пілінги;</span>\r\n<span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif; color: #000000;\">•підбір домашнього догляду.</span>\r\n\r\n<span style=\"color: #000000;\"><em><span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif;\">Все вказане виконується лише на професійній космецевтиці.</span></em></span>\r\n<span style=\"color: #000000;\"><em><span style=\"font-size: 14pt; font-family: tahoma, arial, helvetica, sans-serif;\">Обожнюю робити людей красивими,здоровими та щасливими🌸</span></em></span>[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"400\" title=\"Ультразвукова чистка\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"450\" title=\"Механічна чистка\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"500\" title=\"Комбінована\"][/pricing_item][/vc_column][/vc_row][vc_row][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"600\" title=\"Чистка + пілінг\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"400\" title=\"Карбоксітерапія\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"450\" title=\"Мигдальний пілінг\"][/pricing_item][/vc_column][/vc_row][vc_row][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"450\" title=\"Молочний пілінг\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"350\" title=\"Масаж обличчя+альгінатна маска\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"450\" title=\"Масаж обличчя + золота маска від dr.Kadir\"][/pricing_item][/vc_column][/vc_row][vc_row][vc_column width=\"1/3\"][vc_empty_space][/vc_column][vc_column width=\"1/3\"][pricing_item currency_pos=\"right\" featured=\"0\" currency=\"грн\" price=\"1500\" title=\"prx t 33\"][/pricing_item][/vc_column][vc_column width=\"1/3\"][vc_empty_space][/vc_