INSERT INTO `wpj4_posts` VALUES (1617,1,'2021-11-09 13:06:45','2021-11-09 13:06:45','[vc_row css=\".vc_custom_1636099040887{margin-top: 200px !important;}\"][vc_column css=\".vc_custom_1636099071229{margin-top: 70px !important;}\"][vc_column_text]<img class=\"size-full wp-image-1567 aligncenter\" src=\"https://test.med.uz.ua/wp-content/uploads/2021/11/808080-1.jpg\" alt=\"\" width=\"1301\" height=\"441\" />[/vc_column_text][/vc_column][/vc_row][vc_row full_width=\"stretch_row\" css=\".vc_custom_1636454488794{padding-top: 0px !important;background-color: #ffffff !important;}\"][vc_column][vc_column_text]\r\n<p style=\"text-align: center;\"><a href=\"tel:+380997770758\"><span style=\"font-size: 28px;\">Тел: (099) 777-07-58</span></a></p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row full_width=\"stretch_row\" css=\".vc_custom_1569662678180{background-color: #285bbb !important;}\"][vc_column][cz_gap height=\"90px\" height_tablet=\"0px\"][/vc_column][/vc_row][vc_row full_width=\"stretch_row\" css=\".vc_custom_1569662678180{background-color: #285bbb !important;}\"][vc_column width=\"1/2\"][cz_gap height=\"5px\"][/vc_column][vc_column width=\"1/2\" css=\".vc_custom_1569833803198{padding-right: 60px !important;padding-left: 60px !important;}\"][cz_title shape=\"image\" smart_fs=\"true\" text_center=\"true\" id=\"cz_86599\" sk_overall=\"margin-top:60px;margin-bottom:60px;\" image=\"1191\" sk_shape=\"top:-30px;right:0px;left:auto;\" sk_shape_mobile=\"display:none;top:-28px;right:20%;\"]<span style=\"font-family: Tahoma; font-size: 24px; color: #ffffff;\">Збережіть свій зір –</span>\r\n\r\n<span style=\"font-family: Tahoma; font-size: 24px; color: #ffffff;\">Європейська якість медичної допомоги</span>[/cz_title][/vc_column][/vc_row][vc_row full_width=\"stretch_row_content_no_spaces\"][vc_column width=\"1/2\"][cz_image id=\"cz_93785\" image=\"293\" sk_css=\"margin-top:-220px;border-radius:0 5px 5px 0;\" sk_css_mobile=\"margin-top:-20px;margin-right:40px;margin-left:40px;\"]