INSERT INTO `wpj4_posts` VALUES (1993,1,'2022-06-21 21:45:06','2022-06-21 21:45:06','[vc_row css=\".vc_custom_1654511834477{margin-top: -100px !important;}\"][vc_column][vc_column_text]\r\n<table class=\"widefat\">\r\n<tbody>\r\n<tr class=\"pbc-down\" data-down=\"yrc_1578085827\">\r\n<td>[yourchannel user=\"Ваш офтальмолог\"]</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n[/vc_column_text][/vc_column][/vc_row]','Відео','','inherit','closed','closed','','353-revision-v1','','','2022-06-21 21:45:06','2022-06-21 21:45:06','',353,'https://test.med.uz.ua/?p=1993',0,'revision','',0);
