INSERT INTO `wpj4_wc_admin_notes` VALUES (1,'wc-admin-onboarding-email-marketing','info','en_US','Tips, product updates, and inspiration','We\'re here for you - get tips, product updates and inspiration straight to your email box','[]','unactioned','woocommerce-admin','2020-12-26 20:10:24',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (2,'wc-admin-marketing-intro','info','en_US','Connect with your audience','Grow your customer base and increase your sales with marketing tools built for WooCommerce.','[]','unactioned','woocommerce-admin','2020-12-26 20:10:24',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (3,'ecomm-need-help-setting-up-your-store','info','en_US','Need help setting up your Store?','Schedule a free 30-min <a href=\"https://wordpress.com/support/concierge-support/\">quick start session</a> and get help from our specialists. We’re happy to walk through setup steps, show you around the WordPress.com dashboard, troubleshoot any issues you may have, and help you the find the features you need to accomplish your goals for your site.','{}','pending','woocommerce.com','2020-12-26 20:10:24',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (4,'woocommerce-services','info','en_US','WooCommerce Shipping & Tax','WooCommerce Shipping &amp; Tax helps get your store \"ready to sell\" as quickly as possible. You create your products. We take care of tax calculation, payment processing, and shipping label printing! Learn more about the extension that you just installed.','{}','pending','woocommerce.com','2020-12-26 20:10:24',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (5,'ecomm-unique-shopping-experience','info','en_US','For a shopping experience as unique as your customers','Product Add-Ons allow your customers to personalize products while they\'re shopping on your online store. No more follow-up email requests—customers get what they want, before they\'re done checking out. Learn more about this extension that comes included in your plan.','{}','pending','woocommerce.com','2020-12-26 20:10:24',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (6,'wcpay-promo-2020-11','marketing','en_US','wcpay-promo-2020-11','wcpay-promo-2020-11','{}','pending','woocommerce.com','2020-12-26 20:10:24',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (7,'wcpay-subscriptions-2020-11','marketing','en_US','Manage subscriber payments from your store\'s dashboard','Securely accept cards and manage transactions right from your dashboard with <a href=\"https://woocommerce.com/payments/?utm_medium=notification&amp;utm_source=product&amp;utm_campaign=wcpay_ctrl20\" target=\"_blank\">WooCommerce Payments</a>  – now supporting <a href=\"https://woocommerce.com/products/woocommerce-subscriptions/?utm_medium=notification&amp;utm_source=product&amp;utm_campaign=wcpay_ctrl20\" target=\"_blank\">WooCommerce Subscriptions</a>! <br /><br /><em>By clicking \"Install now,\" you agree to our <a href=\"https://wordpress.com/tos/?utm_medium=notification&amp;utm_source=product&amp;utm_campaign=wcpay_ctrl20\" target=\"_blank\">Terms of Service</a>.</em>','[]','pending','woocommerce.com','2020-12-26 20:10:24',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (8,'wcpay-promo-2020-12','marketing','en_US','wcpay-promo-2020-12','wcpay-promo-2020-12','{}','pending','woocommerce.com','2020-12-26 20:10:24',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (9,'wcpay-subscriptions-2020-12','marketing','en_US','Manage payments from your store\'s dashboard','Securely accept cards and manage transactions right from your dashboard with <a href=\"https://woocommerce.com/payments/?utm_medium=notification&amp;utm_source=product&amp;utm_campaign=wcpay_ctrl20\" target=\"_blank\">WooCommerce Payments</a>! Zero setup fees or monthly fees. Just pay-as-you-go, starting at just 2.9% + $0.30 per transaction for U.S.-issued cards. <br /><br /><em>By clicking \"Install now,\" you agree to our <a href=\"https://wordpress.com/tos/?utm_medium=notification&amp;utm_source=product&amp;utm_campaign=wcpay_ctrl20\" target=\"_blank\">Terms of Service</a>.</em>','[]','pending','woocommerce.com','2020-12-26 20:10:24',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (10,'wc-admin-wc-helper-connection','info','en_US','Connect to WooCommerce.com','Connect to get important product notifications and updates.','[]','unactioned','woocommerce-admin','2020-12-26 20:10:24',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (11,'wc-admin-mobile-app','info','en_US','Install Woo mobile app','Install the WooCommerce mobile app to manage orders, receive sales notifications, and view key metrics — wherever you are.','[]','unactioned','woocommerce-admin','2020-12-28 20:14:31',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (12,'wc-admin-onboarding-payments-reminder','info','en_US','Start accepting payments on your store!','Take payments with the provider that’s right for you - choose from 100+ payment gateways for WooCommerce.','[]','unactioned','woocommerce-admin','2020-12-31 20:14:45',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (13,'wc-admin-store-notice-giving-feedback-2','info','en_US','Give feedback','Now that you’ve chosen us as a partner, our goal is to make sure we\'re providing the right tools to meet your needs. We\'re looking forward to having your feedback on the store setup experience so we can improve it in the future.','[]','unactioned','woocommerce-admin','2021-01-03 20:11:07',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (14,'wc-admin-insight-first-sale','survey','en_US','Did you know?','A WooCommerce powered store needs on average 31 days to get the first sale. You\'re on the right track! Do you find this type of insight useful?','[]','unactioned','woocommerce-admin','2021-01-03 20:11:07',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (16,'your-first-product','info','en_US','Your first product','That’s huge! You’re well on your way to building a successful online store — now it’s time to think about how you’ll fulfill your orders.<br /><br />Read our shipping guide to learn best practices and options for putting together your shipping strategy. And for WooCommerce stores in the United States, you can print discounted shipping labels via USPS with <a href=\"https://href.li/?https://woocommerce.com/shipping\" target=\"_blank\">WooCommerce Shipping</a>.','{}','unactioned','woocommerce.com','2021-04-28 20:13:14',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (17,'wc-admin-getting-started-in-ecommerce','info','en_US','Getting Started in eCommerce - webinar','We want to make eCommerce and this process of getting started as easy as possible for you. Watch this webinar to get tips on how to have our store up and running in a breeze.','{}','pending','woocommerce.com','2021-01-27 20:18:29',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (18,'wc-square-apple-pay-boost-sales','marketing','en_US','Boost sales with Apple Pay','Now that you accept Apple Pay® with Square you can increase conversion rates by letting your customers know that Apple Pay® is available. Here’s a marketing guide to help you get started.','{}','pending','woocommerce.com','2021-02-11 21:06:14',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (19,'wc-square-apple-pay-grow-your-business','marketing','en_US','Grow your business with Square and Apple Pay ','Now more than ever, shoppers want a fast, simple, and secure online checkout experience. Increase conversion rates by letting your customers know that you now accept Apple Pay®.','{}','pending','woocommerce.com','2021-02-11 21:06:14',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (20,'facebook_pixel_api_2021','marketing','en_US','Improve the performance of your Facebook ads','Enable Facebook Pixel and Conversions API through the latest version of Facebook for WooCommerce for improved measurement and ad targeting capabilities.','{}','pending','woocommerce.com','2021-02-12 20:29:51',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (21,'facebook_ec_2021','marketing','en_US','Sync your product catalog with Facebook to help boost sales','A single click adds all products to your Facebook Business Page shop. Product changes are automatically synced, with the flexibility to control which products are listed.','{}','pending','woocommerce.com','2021-02-12 20:29:51',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (22,'wc-admin-optimizing-the-checkout-flow','info','en_US','Optimizing the checkout flow','It’s crucial to get your store’s checkout as smooth as possible to avoid losing sales. Let’s take a look at how you can optimize the checkout experience for your shoppers.','{}','unactioned','woocommerce.com','2021-05-02 18:25:47',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (23,'wc-admin-first-five-things-to-customize','info','en_US','The first 5 things to customize in your store','Deciding what to start with first is tricky. To help you properly prioritize, we’ve put together this short list of the first few things you should customize in WooCommerce.','{}','unactioned','woocommerce.com','2021-02-17 20:38:02',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (24,'wc-admin-effortless-payments-by-mollie','info','en_US','Effortless payments by Mollie','Offer global and local payment methods, get onboarded in minutes and supported in your language – try it now!','[]','pending','woocommerce.com','2021-02-20 20:22:27',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (25,'wcpay-apple-pay-boost-sales','marketing','en_US','Boost sales with Apple Pay','Now that you accept Apple Pay® with WooCommerce Payments you can increase conversion rates by letting your customers know that Apple Pay® is available. Here’s a marketing guide to help you get started.','{}','pending','woocommerce.com','2021-03-20 20:11:35',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (26,'wcpay-apple-pay-grow-your-business','marketing','en_US','Grow your business with WooCommerce Payments and Apple Pay','Now more than ever, shoppers want a fast, simple, and secure online checkout experience. Increase conversion rates by letting your customers know that you now accept Apple Pay®.','{}','pending','woocommerce.com','2021-03-20 20:11:35',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (27,'wc-admin-real-time-order-alerts','info','en_US','Get real-time order alerts anywhere','Get notifications about store activity, including new orders and product reviews directly on your mobile devices with the Woo app.','[]','unactioned','woocommerce-admin','2021-03-26 20:12:07',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (28,'wcpay-apple-pay-is-now-available','marketing','en_US','Apple Pay is now available with WooCommerce Payments!','Increase your conversion rate by offering a fast and secure checkout with <a href=\"https://woocommerce.com/apple-pay/?utm_source=inbox&amp;utm_medium=product&amp;utm_campaign=wcpay_applepay\" target=\"_blank\">Apple Pay</a>®. It’s free to get started with <a href=\"https://woocommerce.com/payments/?utm_source=inbox&amp;utm_medium=product&amp;utm_campaign=wcpay_applepay\" target=\"_blank\">WooCommerce Payments</a>.','{}','pending','woocommerce.com','2021-03-30 20:34:48',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (29,'paypal_ppcp_gtm_2021','marketing','en_US','Offer more options with the new PayPal','Get the latest PayPal extension for a full suite of payment methods with extensive currency and country coverage.','{}','pending','woocommerce.com','2021-04-01 20:21:51',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (30,'wc-payments-qualitative-feedback','info','en_US','WooPayments setup - let us know what you think','Congrats on enabling WooPayments for your store. Please share your feedback in this 2 minute survey to help us improve the setup process.','{}','pending','woocommerce.com','2021-04-16 20:18:13',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (31,'wc-update-db-reminder','update','en_US','Оновлення бази даних WooCommerce завершено','Оновлення WooCommerce завершено. Дякуємо за оновлення до останньої версії!','{}','unactioned','woocommerce-core','2021-04-27 22:52:46',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (32,'wc-admin-choosing-a-theme','marketing','en_US','Choosing a theme?','Check out the themes that are compatible with WooCommerce and choose one aligned with your brand and business needs.','[]','unactioned','woocommerce-admin','2021-04-28 20:13:14',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (33,'wc-admin-insight-first-product-and-payment','survey','en_US','Insight','More than 80% of new merchants add the first product and have at least one payment method set up during the first week. We\'re here to help your business succeed! Do you find this type of insight useful?','[]','unactioned','woocommerce-admin','2021-04-28 20:13:14',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (35,'share-your-feedback-on-paypal','info','en_US','Share your feedback on PayPal','Share your feedback in this 2 minute survey about how we can make the process of accepting payments more useful for your store.','{}','pending','woocommerce.com','2021-05-13 20:27:20',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (36,'wc-admin-learn-more-about-variable-products','info','en_US','Learn more about variable products','Variable products are a powerful product type that lets you offer a set of variations on a product, with control over prices, stock, image and more for each variation. They can be used for a product like a shirt, where you can offer a large, medium and small and in different colors.','[]','unactioned','woocommerce-admin','2021-05-14 18:29:28',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (37,'wc-pb-bulk-discounts','info','en_US','Ready to start offering bulk discounts?','			<p>Did you know that you can use <strong>Product Bundles</strong> to offer bulk quantity discounts? </p>\n			<p>Grab the free <strong>Bulk Discounts</strong> add-on, and offer lower prices to those who purchase more!</p>\n			','[]','unactioned','woocommerce-product-bundles','2021-05-14 18:53:58',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (38,'wcpay_instant_deposits_gtm_2021','marketing','en_US','Get paid within minutes – Instant Deposits for WooCommerce Payments','Stay flexible with immediate access to your funds when you need them – including nights, weekends, and holidays. With <a href=\"https://woocommerce.com/products/woocommerce-payments/?utm_source=inbox&amp;utm_medium=product&amp;utm_campaign=wcpay_instant_deposits\">WooCommerce Payments\'</a> new Instant Deposits feature, you’re able to transfer your earnings to a debit card within minutes.','{}','pending','woocommerce.com','2021-05-14 20:10:27',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (39,'wc-admin-filter-by-product-variations-in-reports','info','en_US','New - filter by product variations in orders and products reports','One of the most awaited features has just arrived! You can now have insights into each product variation in the orders and products reports.','[]','unactioned','woocommerce-admin','2021-05-24 20:11:02',NULL,0,'banner','https://test.med.uz.ua/wp-content/plugins/woocommerce/packages/woocommerce-admin/images/admin_notes/filter-by-product-variations-note.svg',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (40,'wc-admin-orders-milestone','info','en_US','Вітаємо з обробкою 10 замовлень!','Ви досягли рівня в 10 замовлень! Подивіться на свій прогрес. Для мотивації перегляньте деякі історії успіху користувачів WooCommerce.','[]','unactioned','woocommerce-admin','2021-05-26 07:18:41',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (41,'wc-subscriptions-security-update-3-0-15','info','en_US','WooCommerce Subscriptions security update!','We recently released an important security update to WooCommerce Subscriptions. To ensure your site’s data is protected, please upgrade <strong>WooCommerce Subscriptions to version 3.0.15</strong> or later.<br /><br />Click the button below to view and update to the latest Subscriptions version, or log in to <a href=\"https://woocommerce.com/my-dashboard\">WooCommerce.com Dashboard</a> and navigate to your <strong>Downloads</strong> page.<br /><br />We recommend always using the latest version of WooCommerce Subscriptions, and other software running on your site, to ensure maximum security.<br /><br />If you have any questions we are here to help — just <a href=\"https://woocommerce.com/my-account/create-a-ticket/\">open a ticket</a>.','{}','pending','woocommerce.com','2021-05-31 20:14:52',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (42,'google_listings_and_ads_install','marketing','en_US','Drive traffic and sales with Google','Reach online shoppers to drive traffic and sales for your store by showcasing products across Google, for free or with ads.','{}','unactioned','woocommerce.com','2021-06-09 20:11:00',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (43,'woocommerce-core-update-5-4-0','info','en_US','Update to WooCommerce 5.4.1 now','WooCommerce 5.4.1 addresses a checkout issue discovered in WooCommerce 5.4. We recommend upgrading to WooCommerce 5.4.1 as soon as possible.','{}','pending','woocommerce.com','2021-06-10 20:10:24',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (44,'wcpay-promo-2021-6-incentive-1','marketing','en_US','Simplify the payments process for you and your customers with WooCommerce Payments','With <a href=\"https://woocommerce.com/payments/?utm_medium=notification&amp;utm_source=product&amp;utm_campaign=wcpay601\">WooCommerce Payments</a>, you can securely accept all major cards, Apple Pay®, and recurring revenue in over 100 currencies.\n				Built into your store’s WooCommerce dashboard, track cash flow and manage all of your transactions in one place – with no setup costs or monthly fees.\n				<br /><br />\n				By clicking \"Get WooCommerce Payments,\" you agree to the <a href=\"https://wordpress.com/tos/?utm_medium=notification&amp;utm_source=product&amp;utm_campaign=wcpay601\">Terms of Service</a>\n				and acknowledge you have read the <a href=\"https://automattic.com/privacy/\">Privacy Policy</a>.\n				','{}','pending','woocommerce.com','2021-06-12 20:11:13',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (45,'wcpay-promo-2021-6-incentive-2','marketing','en_US','Simplify the payments process for you and your customers with WooCommerce Payments','With <a href=\"https://woocommerce.com/payments/?utm_medium=notification&amp;utm_source=product&amp;utm_campaign=wcpay601\">WooCommerce Payments</a>, you can securely accept all major cards, Apple Pay®, and recurring revenue in over 100 currencies.\n				Built into your store’s WooCommerce dashboard, track cash flow and manage all of your transactions in one place – with no setup costs or monthly fees.\n				<br /><br />\n				By clicking \"Get WooCommerce Payments,\" you agree to the <a href=\"https://wordpress.com/tos/?utm_medium=notification&amp;utm_source=product&amp;utm_campaign=wcpay601\">Terms of Service</a>\n				and acknowledge you have read the <a href=\"https://automattic.com/privacy/\">Privacy Policy</a>.\n				','{}','pending','woocommerce.com','2021-06-12 20:11:13',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (46,'ppxo-pps-upgrade-paypal-payments-1','info','en_US','Get the latest PayPal extension for WooCommerce','Heads up! There’s a new PayPal on the block!<br /><br />Now is a great time to upgrade to our latest <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">PayPal extension</a> to continue to receive support and updates with PayPal.<br /><br />Get access to a full suite of PayPal payment methods, extensive currency and country coverage, and pay later options with the all-new PayPal extension for WooCommerce.','{}','pending','woocommerce.com','2021-06-22 20:11:07',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (47,'ppxo-pps-upgrade-paypal-payments-2','info','en_US','Upgrade your PayPal experience!','Get access to a full suite of PayPal payment methods, extensive currency and country coverage, offer subscription and recurring payments, and the new PayPal pay later options.<br /><br />Start using our <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">latest PayPal today</a> to continue to receive support and updates.','{}','pending','woocommerce.com','2021-06-22 20:11:07',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (48,'eu_vat_changes_2021','marketing','en_US','Get your business ready for the new EU tax regulations','On July 1, 2021, new taxation rules will come into play when the <a href=\"https://ec.europa.eu/taxation_customs/business/vat/modernising-vat-cross-border-ecommerce_en\">European Union (EU) Value-Added Tax (VAT) eCommerce package</a> takes effect.<br /><br />The new regulations will impact virtually every B2C business involved in cross-border eCommerce trade with the EU.<br /><br />We therefore recommend <a href=\"https://woocommerce.com/posts/new-eu-vat-regulations\">familiarizing yourself with the new updates</a>, and consult with a tax professional to ensure your business is following regulations and best practice.','{}','unactioned','woocommerce.com','2021-06-24 20:11:05',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (49,'wc-admin-manage-orders-on-the-go','info','en_US','Manage your orders on the go','Look for orders, customer info, and process refunds in one click with the Woo app.','[]','unactioned','woocommerce-admin','2021-06-24 20:11:05',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (50,'wayflyer_q3_2021','marketing','en_US','Grow your revenue with Wayflyer financing and analytics','Flexible financing tailored to your needs by <a href=\"https://woocommerce.com/products/wayflyer/\">Wayflyer</a> – one fee, no interest rates, penalties, equity, or personal guarantees. Based on your store\'s performance, Wayflyer can provide the financing you need to grow and the analytical insights to help you spend it.','{}','pending','woocommerce.com','2021-07-15 20:10:28',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (51,'woocommerce-core-sqli-july-2021-need-to-update','update','en_US','Action required: Critical vulnerabilities in WooCommerce','In response to a critical vulnerability identified on July 13, 2021, we are working with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br />Our investigation into this vulnerability is ongoing, but <strong>we wanted to let you know now about the importance of updating immediately</strong>.<br /><br />For more information on which actions you should take, as well as answers to FAQs, please urgently review our blog post detailing this issue.','{}','unactioned','woocommerce.com','2021-07-15 20:10:28',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (52,'woocommerce-blocks-sqli-july-2021-need-to-update','update','en_US','Action required: Critical vulnerabilities in WooCommerce Blocks','In response to a critical vulnerability identified on July 13, 2021, we are working with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br />Our investigation into this vulnerability is ongoing, but <strong>we wanted to let you know now about the importance of updating immediately</strong>.<br /><br />For more information on which actions you should take, as well as answers to FAQs, please urgently review our blog post detailing this issue.','{}','pending','woocommerce.com','2021-07-15 20:10:28',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (53,'woocommerce-core-sqli-july-2021-store-patched','update','en_US','Solved: Critical vulnerabilities patched in WooCommerce','In response to a critical vulnerability identified on July 13, 2021, we worked with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br /><strong>Your store has been updated to the latest secure version(s)</strong>. For more information and answers to FAQs, please review our blog post detailing this issue.','{}','pending','woocommerce.com','2021-07-15 20:10:28',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (54,'woocommerce-blocks-sqli-july-2021-store-patched','update','en_US','Solved: Critical vulnerabilities patched in WooCommerce Blocks','In response to a critical vulnerability identified on July 13, 2021, we worked with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br /><strong>Your store has been updated to the latest secure version(s)</strong>. For more information and answers to FAQs, please review our blog post detailing this issue.','{}','pending','woocommerce.com','2021-07-15 20:10:28',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (55,'mercadopago_q3_2021_EN','marketing','en_US','Get paid with Mercado Pago Checkout','Latin America\'s leading payment processor is now available for WooCommerce stores. Securely accept debit and credit cards, cash, bank transfers, and installment payments – backed by exclusive fraud prevention tools.','[]','pending','woocommerce.com','2021-08-31 20:10:24',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (56,'wc-admin-performance-on-mobile','info','en_US','Track your store performance on mobile','Monitor your sales and high performing products with the Woo app.','[]','unactioned','woocommerce-admin','2021-09-22 20:10:26',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (57,'bbpos-chipper-launch','marketing','en_US','Ready to grow your business beyond online?','Collect payment in person for orders placed online using WooCommerce In-Person Payments. The BBPOS Chipper card reader can process payments securely, and keep everything synced in your WooCommerce Payments dashboard – no matter where you are.','{}','pending','woocommerce.com','2021-10-15 20:15:40',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (58,'habit-moment-survey','marketing','en_US','We’re all ears! Share your experience so far with WooCommerce','We’d love your input to shape the future of WooCommerce together. Feel free to share any feedback, ideas or suggestions that you have.','{}','pending','woocommerce.com','2021-11-04 20:26:36',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (59,'new_in_app_marketplace_2021_1','info','en_US','Grow your business with extensions','Check out our NEW Extensions tab to see our favorite extensions for growing your business, and discover the most popular extensions in the WooCommerce Marketplace.','{}','pending','woocommerce.com','2021-11-08 20:58:02',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (60,'new_in_app_marketplace_2021_2','info','en_US','Customize your store with extensions','Check out our NEW Extensions tab to see our favorite extensions for customizing your store, and discover the most popular extensions in the WooCommerce Marketplace.','{}','pending','woocommerce.com','2021-11-08 20:58:02',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (61,'stripe_applepay_holiday2021','marketing','en_US','Boost sales this holiday season with Apple Pay!','Increase your conversion rate by letting your customers know that you accept Apple Pay. It’s seamless to <a href=\"https://docs.woocommerce.com/document/stripe/?_ga=2.90941597.642705274.1635776464-1391993999.1621950839#apple-pay\">enable Apple Pay with Stripe</a> and easy to communicate it with this <a href=\"https://developer.apple.com/apple-pay/marketing/\">marketing guide</a>.','{}','pending','woocommerce.com','2021-11-11 20:20:17',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (62,'square_applepay_holiday2021','marketing','en_US','Boost sales this holiday season with Apple Pay!','Increase your conversion rate by letting your customers know that you accept Apple Pay. It’s seamless to <a href=\"https://docs.woocommerce.com/document/woocommerce-square/?_ga=2.90941597.642705274.1635776464-1391993999.1621950839#section-14\">enable Apple Pay with Square</a> and easy to communicate it with this <a href=\"https://developer.apple.com/apple-pay/marketing/\">marketing guide</a>.','{}','pending','woocommerce.com','2021-11-11 20:20:17',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (63,'wcpay_applepay_holiday2021','marketing','en_US','Boost sales this holiday season with Apple Pay!','Increase your conversion rate by letting your customers know that you accept Apple Pay. It’s seamless to <a href=\"https://docs.woocommerce.com/document/payments/apple-pay/\">enable Apple Pay with WooCommerce Payments</a> and easy to communicate it with this <a href=\"https://developer.apple.com/apple-pay/marketing/\">marketing guide</a>.','{}','pending','woocommerce.com','2021-11-11 20:20:17',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (64,'wayflyer_bnpl_q4_2021','marketing','en_US','Grow your business with funding through Wayflyer','Fast, flexible financing to boost cash flow and help your business grow – one fee, no interest rates, penalties, equity, or personal guarantees. Based on your store’s performance, Wayflyer provides funding and analytical insights to invest in your business.','{}','pending','woocommerce.com','2021-11-11 20:20:17',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (65,'wc_shipping_mobile_app_usps_q4_2021','marketing','en_US','Print and manage your shipping labels with WooCommerce Shipping and the WooCommerce Mobile App','Save time by printing, purchasing, refunding, and tracking shipping labels generated by <a href=\"https://woocommerce.com/woocommerce-shipping/\">WooCommerce Shipping</a> – all directly from your mobile device!','{}','pending','woocommerce.com','2021-11-11 20:20:17',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (66,'wc_shipping_mobile_app_q4_2021','marketing','en_US','Print and manage your shipping labels with the WooCommerce Mobile App','Save time by printing, purchasing, refunding, and tracking shipping labels generated by <a href=\"https://woocommerce.com/woocommerce-shipping/\">WooCommerce Shipping</a> – all directly from your mobile device!','{}','pending','woocommerce.com','2021-11-11 20:20:17',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (67,'new_in_app_marketplace_2021','info','en_US','Customize your store with extensions','Check out our NEW Extensions tab to see our favorite extensions for customizing your store, and discover the most popular extensions in the WooCommerce Marketplace.','{}','pending','woocommerce.com','2021-11-23 20:45:00',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (68,'wc-admin-edit-products-on-the-move','info','en_US','Edit products on the move','Edit and create new products from your mobile devices with the Woo app','{}','unactioned','woocommerce-admin','2021-12-27 22:28:50',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (69,'ecomm-wc-navigation-survey','info','en_US','We’d like your feedback on the WooCommerce navigation','We’re making improvements to the WooCommerce navigation and would love your feedback. Share your experience in this 2 minute survey.','{}','pending','woocommerce.com','2022-01-05 21:48:46',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (70,'wc_simple_payments_m2_reader_launch_q1_2022','marketing','en_US','Take quick and easy in-person payments','WooCommerce is continuing to power up your business with our new Simple Payments feature, built exclusively for WooCommerce In-Person Payments. Capture quick and simple payments anywhere else your customers are – or offer a local pickup option with payment taken in-person for orders placed online.','{}','pending','woocommerce.com','2022-02-04 00:00:07',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (71,'wcpay_applepay_q1_2022','marketing','en_US','Increase conversions with Apple Pay – just like Diane does','See how Diane from <a href=\"https://woocommerce.com/posts/lady-dye-yarns-from-crafts-to-activism-with-woocommerce/?utm_source=product&amp;utm_medium=inboxnotification&amp;utm_campaign=apple-pay\" target=\"_blank\">Lady Dye Yarns</a> uses Apple Pay to provide customers with the fast, secure checkout experience they love. You can, too – Apple Pay is included in WooCommerce Payments. Here\'s how you can increase conversions by encouraging shoppers to pay with a single tap.','{}','pending','woocommerce.com','2022-02-07 21:58:19',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (72,'stripe_applepay_q1_2022','marketing','en_US','Increase conversions with Apple Pay – just like Thomas does','Read the inspirational story of <a href=\"https://woocommerce.com/posts/incredible-story-of-thomas-trendy-socks-down-syndrome-entrepreneur/?utm_source=product&amp;utm_medium=inboxnotification&amp;utm_campaign=apple-pay\" target=\"_blank\">Thomas\'s Trendy Socks</a> and see how he’s using Apple Pay to provide customers with the fast, secure checkout experience they love. You can, too – ready to turn more visitors into buyers? Accept Apple Pay by selecting Enable express checkouts in Settings &gt; Payments &gt; Stripe.','{}','pending','woocommerce.com','2022-02-07 21:58:19',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (73,'square_applepay_q1_2022','marketing','en_US','Increase conversions with a faster checkout experience','By enabling Apple Pay in Square, your customers can complete purchases quickly and securely with a single touch or a glance – no lengthy checkout forms necessary. Accept Apple Pay by enabling Digital Wallets within Settings &gt; Payments &gt; Square.','{}','pending','woocommerce.com','2022-02-07 21:58:19',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (74,'lead_gen_existing_customers_1','marketing','en_US','Talk to a consultant','As your business grows, you want to optimize costs, streamline operations, and sell more. We can help. Talk to us about how you can get the most out of WooCommerce.','{}','pending','woocommerce.com','2022-02-11 21:37:14',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (75,'woocommerce-core-paypal-march-2022-updated','update','en_US','Security auto-update of WooCommerce','<strong>Your store has been updated to the latest secure version of WooCommerce</strong>. We worked with WordPress to deploy PayPal Standard security updates for stores running WooCommerce (version 3.5 to 6.3). It’s recommended to disable PayPal Standard, and use <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">PayPal Payments</a> to accept PayPal.','{}','pending','woocommerce.com','2022-03-14 17:09:47',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (76,'woocommerce-core-paypal-march-2022-updated-nopp','update','en_US','Security auto-update of WooCommerce','<strong>Your store has been updated to the latest secure version of WooCommerce</strong>. We worked with WordPress to deploy security updates related to PayPal Standard payment gateway for stores running WooCommerce (version 3.5 to 6.3).','{}','pending','woocommerce.com','2022-03-14 17:09:47',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (77,'pinterest_03_2022_update','marketing','en_US','Your Pinterest for WooCommerce plugin is out of date!','Update to the latest version of Pinterest for WooCommerce to continue using this plugin and keep your store connected with Pinterest. To update, visit <strong>Plugins &gt; Installed Plugins</strong>, and click on “update now” under Pinterest for WooCommerce.','{}','pending','woocommerce.com','2022-03-24 18:09:32',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (78,'pinterest_gtm_q2_2021','marketing','en_US','Get your products in front of a large, engaged audience','Did you know that shoppers on Pinterest spend twice as much as people on other social platforms? With the new, official Pinterest for WooCommerce, you can turn your product catalog into shoppable Pins and showcase them to 400+ million monthly users looking to buy.','{}','unactioned','woocommerce.com','2022-04-24 06:34:05',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (79,'setup_task_initiative_survey_q2_2022','survey','en_US','We want to know what matters most to you','Take 2 minutes to give us your input on what is important for you while setting up your store and help shape the future of WooCommerce together.','{}','pending','woocommerce.com','2022-04-27 03:43:50',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (80,'woocommerce_payments_subscriptions_nopayments_q2_2022','marketing','en_US','Sell subscriptions online – without a paid extension','Say hello to WooCommerce Payments – now with built-in subscriptions functionality. Get free access to the features you need to start earning recurring revenue online. Pay as you go, with no setup costs or monthly fees.','{}','pending','woocommerce.com','2022-04-27 03:43:50',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (81,'woocommerce_payments_subscriptions_yespayments_q2_2022','marketing','en_US','Sell subscriptions online – no extra extension required','It\'s here! WooCommerce Payments now features built-in subscriptions functionality. No need to install an extra, paid extension – we\'ve made it simpler than ever to start earning recurring revenue. Ready to grow your business?','{}','pending','woocommerce.com','2022-04-27 03:43:50',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (82,'setup_task_second_survey_q2_2022','survey','en_US','We want to know what matters most to you','Take 2 minutes to give us your input on what is important for you while setting up your store and help shape the future of WooCommerce together.','{}','pending','woocommerce.com','2022-05-11 01:35:38',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (83,'store_setup_survey_survey_q2_2022','survey','en_US','How is your store setup going?','Our goal is to make sure you have all the right tools to start setting up your store in the smoothest way possible.\r\nWe’d love to know if we hit our mark and how we can improve. To collect your thoughts, we made a 2-minute survey.','{}','pending','woocommerce.com','2022-05-11 01:35:38',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (84,'affirm_q2_2022','marketing','en_US','Boost your business with flexible payments','Expand your customer base with smarter payment options for more shoppers. With Affirm,  you can offer the most relevant payment options at every price point – from four interest-free payments every two weeks to longer installments up to 36 months. Fast-track your revenue goals today!','{}','pending','woocommerce.com','2022-05-15 01:44:46',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (85,'wc-admin-EU-consumer-protection','marketing','en_US','Important changes to EU consumer protection laws','New regulations to help modernize and strengthen consumer protection laws in the European Union (EU) take effect on May 28, 2022. These rules impact all merchants selling to the EU, regardless of where their business is located. Further detailed information is available on the European Commission\'s official website.','{}','unactioned','woocommerce.com','2022-05-15 01:44:46',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (86,'googlelistings_multicountrygtm_q22022','marketing','en_US','Expand your audience with Multi-Country Advertising','It\'s time to expand your audience with Multi-Country Advertising, an exciting new feature in Google Listings &amp; Ads. Reach more potential customers in as many regions as you like within a single campaign, all from the convenience of your WooCommerce dashboard.','{}','unactioned','woocommerce.com','2022-05-16 01:18:13',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (87,'wc_ipp_order_creation_GTM_launch_q2_2022','marketing','en_US','Grow your business on the go with WooCommerce In-Person Payments','Quickly create new orders, manage transactions, and take secure payments no matter where your business takes you. With automatic inventory sync, WooCommerce In-Person Payments is the only fully integrated solution for taking your WooCommerce store offline.','{}','pending','woocommerce.com','2022-05-26 02:59:07',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (88,'wc-admin-wisepad3','marketing','en_US','Take your business on the go in Canada with WooCommerce In-Person Payments','Quickly create new orders, accept payment in person for orders placed online, and automatically sync your inventory – no matter where your business takes you. With WooCommerce In-Person Payments and the WisePad 3 card reader, you can bring the power of your store anywhere.','{}','pending','woocommerce.com','2022-06-15 23:31:26',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (89,'TikTok q2_2022','marketing','en_US','Give your store a stage on the world’s fastest-growing advertising channel','With TikTok for WooCommerce, you can sync your catalog, create videos, and track performance in front of TikTok’s one billion global users. Try the Smart Video Generator to make ads using your existing product images – no camera needed. Get $200 in ad credit from TikTok after a $20 spend (terms &amp; conditions apply).','{}','unactioned','woocommerce.com','2022-06-21 20:10:49',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (90,'tiktok-webinar-promo-july2022','marketing','en_US','Free webinar: TikTok for WooCommerce','Join WooCommerce and TikTok live on July 14 to learn about ad types, trends, and the best ways to connect with an audience of one billion active users on the world’s fastest-growing social platform. Participants have a chance to score a free month of Vimeo Pro, and two winners will get a $5,000 ad credit and more.','{}','unactioned','woocommerce.com','2022-07-09 20:39:21',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (91,'klarna_q3_2022','marketing','en_US','Meet Klarna – your ultimate growth partner','Increase conversions by offering secure, flexible payment solutions – including buy now, pay later – all through a one-click checkout experience. Plus, you’ll tap into a whole new market of the world’s most engaged shoppers.','{}','pending','woocommerce.com','2022-08-08 03:32:11',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (92,'mercado_pago_q3_2022','marketing','en_US','Get paid with Mercado Pago Checkout','Give your customers a checkout they can trust with Latin America\'s leading payment processor. Securely accept debit and credit cards, cash, bank transfers, and installment payments – backed by exclusive fraud prevention tools.','{}','pending','woocommerce.com','2022-08-08 20:26:21',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (93,'woocommerce-payments-august-2022-need-to-update','update','en_US','Action required: Please update WooCommerce Payments','An updated secure version of WooCommerce Payments is available – please ensure that you’re using the latest patch version. For more information on what action you need to take, please review the article below.','{}','pending','woocommerce.com','2022-08-09 20:46:18',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (94,'woocommerce-payments-august-2022-store-patched','update','en_US','WooCommerce Payments has been automatically updated','You’re now running the latest secure version of WooCommerce Payments. We’ve worked with the WordPress Plugins team to deploy a security update to stores running WooCommerce Payments (version 3.9 to 4.5). For further information, please review the article below.','{}','pending','woocommerce.com','2022-08-09 20:46:18',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (95,'mobile_app_order_management_q3_2022','marketing','en_US','Take order management on the go','The WooCommerce Mobile App continues to get better with added order management functionality! Add or remove products, edit fees, or change the shipping options in any existing order – all from within the app.','{}','unactioned','woocommerce.com','2022-08-17 20:31:29',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (96,'product_creation_usability_test_3_months','survey','en_US','Have a say in the future of WooCommerce','Take an early look at the future of editing products in WooCommerce. Share your thoughts (~5 minutes) and help shape the experience for yourself and other merchants.','{}','pending','woocommerce.com','2022-08-25 20:53:57',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (97,'product_creation_usability_test_6_months','survey','en_US','Try the new product edit form prototype','Take an early look at the future of editing products in WooCommerce. Share your thoughts (~5 minutes) and help shape the experience for yourself and other merchants.','{}','pending','woocommerce.com','2022-08-29 20:27:41',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (98,'product_creation_usability_test_12_months','survey','en_US','Try the new product edit form prototype','Take an early look at the future of editing products in WooCommerce. Share your thoughts (~5 minutes) and help shape the experience for yourself and other merchants.','{}','pending','woocommerce.com','2022-09-06 20:59:17',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (99,'custom_deposit_schedules_inbox','marketing','en_US','Customize your deposit schedule','Receive your funds according to your own business needs with custom deposit schedules from WooCommerce Payments. You’ll have the flexibility to deposit funds into your bank account daily, weekly, monthly, or even on-demand – you’ve done the work, now get paid on your terms.','{}','pending','woocommerce.com','2022-09-17 00:11:04',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (100,'googlelistings_signals2022_hasGLA','marketing','en_US','Show off your products with Ads on Google','You’re ready to grow with ads. Google optimizes for performance across your products; you only pay for results. If you’re new to Google, you can earn up to $500 in ad credits (T&amp;Cs apply). <a href=\"https://woocommerce.com/my-account/create-a-ticket/\">Contact support</a> if you need guidance with Google Listings &amp; Ads.','{}','pending','woocommerce.com','2022-09-24 04:43:08',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (101,'googlelistings_signals2022_noGLA','marketing','en_US','Show off your products with Ads on Google','You’re ready to grow with ads. Google optimizes for performance across your products; you only pay for results. If you’re new to Google, you can earn up to $500 in ad credits (T&amp;Cs apply). <a href=\"https://woocommerce.com/my-account/create-a-ticket/\">Contact support</a> if you need guidance with Google Listings &amp; Ads.','{}','pending','woocommerce.com','2022-09-24 04:43:08',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (102,'pre-black-friday-sale-2022-announcement','marketing','en_US','Surprise! We’re offering 40% off everything at WooCommerce.com','Just in time to get your store Black Friday ready. Sale ends 7 October, 2pm UTC.','{}','unactioned','woocommerce.com','2022-10-03 20:20:17',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (103,'shipping_category_q4_2022','marketing','en_US','Save time on shipping','Is your store all set to ship? Save valuable time (and money!) by automating your fulfillment process for the busiest shopping season. Explore our range of trusted shipping partners to get started.','{}','unactioned','woocommerce.com','2022-10-13 20:17:36',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (104,'facebook_q4-2022_hasFB','marketing','en_US','Drive more demand this holiday season with Facebook for WooCommerce','Deliver a personalized and seamless shopping experience this holiday season with Facebook for WooCommerce. With more ad formats than ever, you can create engaging ads that meet customers across Facebook, Instagram, Messenger, and WhatsApp throughout the busy shopping season.','{}','pending','woocommerce.com','2022-10-21 04:09:14',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (105,'facebook_q4-2022_noFB','marketing','en_US','Meet your customers where they are with Facebook for WooCommerce','Don’t wait for your customers to come to you – meet them where they’re browsing! Use the Facebook for WooCommerce extension to promote your products on Facebook, Instagram, Messenger, and WhatsApp. Create seamless shopping experiences – straight from your WooCommerce dashboard.','{}','unactioned','woocommerce.com','2022-10-22 20:51:37',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (106,'tiktok-targeted-q4-2022','marketing','en_US','Get $200 in ad credit from TikTok after you spend $20 on your first campaign','Reach one billion shoppers with TikTok for WooCommerce this holiday season! Sync your product catalog, capture insights, and create ad campaigns right from your dashboard. Connect your store today to unlock this limited time offer! <a href=\"https://ads.tiktok.com/help/article?aid=10011326\">Terms &amp; conditions apply</a>.','{}','pending','woocommerce.com','2022-10-25 04:28:31',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (107,'paypal_paylater_g3_q4_22','marketing','en_US','Turn browsers into buyers with Pay Later','Add PayPal at checkout, plus give customers a buy now, pay later option from the name they trust. With Pay in 4 &amp; Pay Monthly, available in PayPal Payments, you get paid up front while letting customers spread their payments over time. Boost your average order value and convert more sales – at no extra cost to you.','{}','pending','woocommerce.com','2022-11-01 20:22:20',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (108,'paypal_paylater_g2_q4_22','marketing','en_US','Upgrade to PayPal Payments to offer Pay Later at checkout','PayPal Pay Later is included in PayPal Payments at no additional cost to you. Customers can spread their payments over time while you get paid up front. \r\nThere’s never been a better time to upgrade your PayPal plugin. Simply download it and connect with a PayPal Business account.','{}','pending','woocommerce.com','2022-11-03 20:28:01',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (109,'woocommerce_admin_deprecation_q4_2022','info','en_US','WooCommerce Admin is part of WooCommerce!','To make sure your store continues to run smoothly, check that WooCommerce is up-to-date – at least version 6.5 – and then disable the WooCommerce Admin plugin.','{}','pending','woocommerce.com','2022-11-04 21:47:06',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (110,'google_listings_ads_custom_attribute_mapping_q4_2022','marketing','en_US','Our latest improvement to the Google Listings & Ads extension: Attribute Mapping','You spoke, we listened. This new feature enables you to easily upload your products, customize your product attributes in one place, and target shoppers with more relevant ads. Extend how far your ad dollars go with each campaign.','{}','pending','woocommerce.com','2022-11-30 20:17:56',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (111,'wc-admin-manualauthcapture','marketing','en_US','Miss fewer manual payments in WooCommerce Payments','Using WooCommerce Payments to manually authorize and capture payments? We’ve introduced a simplified and more efficient process, so you can miss fewer payments and continue to grow your revenue.','{}','pending','woocommerce.com','2022-11-30 20:17:56',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (112,'apple_pay_square_q422','marketing','en_US','Grow your business with Apple Pay','Start boosting your online conversions today with Apple Pay – shoppers can safely complete a purchase with a touch or a glance and are more likely to come back. Enable Apple Pay with Square by selecting  Settings &gt; Payments &gt; Square.','{}','pending','woocommerce.com','2022-12-07 22:13:43',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (113,'apple_pay_wcpay_q422','marketing','en_US','Grow your business with Apple Pay','Start boosting your online conversions today with Apple Pay – shoppers can safely complete a purchase with a touch or a glance and are more likely to come back. Confirm Apple Pay is enabled by selecting Payments &gt; Settings and making sure Enable express checkouts is checked.','{}','pending','woocommerce.com','2022-12-07 22:13:43',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (114,'meta-hasFB-dec-q4-2022','marketing','en_US','Power up your Facebook ad strategy','Did you know that new privacy policies may be decreasing the effectiveness of your Facebook ads? Get back on track with Meta’s Conversion API. It creates a direct connection between the marketing data from your store and Meta, helping you more accurately track, attribute and improve your Facebook marketing performance.','{}','pending','woocommerce.com','2022-12-10 02:07:00',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (115,'meta-noFB-dec-q4-2022','marketing','en_US','Create highly targeted Facebook ads with Facebook for WooCommerce','Sync your product catalog to create Facebook ads and track their performance – all from within your WooCommerce dashboard. With improved tracking signals and speed, plus more accurate tracking with the introduction of Meta’s Conversion API, you’ll have all the tools you need to run effective ad campaigns.','{}','unactioned','woocommerce.com','2022-12-11 20:18:28',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (116,'needs-update-eway-payment-gateway-rin-2022-12-20','update','en_US','Security vulnerability patched in WooCommerce Eway Gateway','In response to a potential vulnerability identified in WooCommerce Eway Gateway versions 3.1.0 to 3.5.0, we’ve worked to deploy security fixes and have released an updated version.\r\nNo external exploits have been detected, but we recommend you update to your latest supported version 3.1.26, 3.2.3, 3.3.1, 3.4.6, or 3.5.1','{}','pending','woocommerce.com','2023-01-04 20:23:37',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (117,'updated-eway-payment-gateway-rin-2022-12-20','update','en_US','WooCommerce Eway Gateway has been automatically updated','Your store is now running the latest secure version of WooCommerce Eway Gateway. We worked with the WordPress Plugins team to deploy a software update to stores running WooCommerce Eway Gateway (versions 3.1.0 to 3.5.0) in response to a security vulnerability that was discovered.','{}','pending','woocommerce.com','2023-01-04 20:23:37',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (118,'storeediting_feedback_jan_2023','marketing','en_US','Tell us what you need to customize your store!','We need your feedback. Please spare a few minutes to share your input on what is most important to you when designing and customizing your storefront to help us build the features you need.','{}','unactioned','woocommerce.com','2023-01-12 22:20:29',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (119,'ecomm-wc-navigation-survey-2023','info','en_US','Navigating WooCommerce on WordPress.com','We are improving the WooCommerce navigation on WordPress.com and would love your help to make it better! Please share your experience with us in this 2-minute survey.','{}','pending','woocommerce.com','2023-01-16 23:01:40',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (120,'affirm_q1_2023','marketing','en_US','Turn more browsers into buyers with flexible payments','When you offer flexible payment options to shoppers, they\'re more likely to convert. It’s why businesses offering Affirm see an average order value lift of 63%. Affirm tailors your store\'s payment options with terms proven to reach new customers, boost conversions, and grow sales.','{}','pending','woocommerce.com','2023-03-13 20:32:22',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (121,'google_listings_ads_pmax_i1_q1_2023_no_gla','marketing','en_US','Create more engaging ads – without the hard work','Get in front of millions of shoppers searching for products like yours with Google Listings &amp; Ads. With new customization features, Google automatically tests multiple combinations of text and images to create the most engaging ad to boost your business. Plus, get up to $500 in ad credit – terms and conditions apply.','{}','unactioned','woocommerce.com','2023-03-16 22:20:01',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (122,'google_listings_ads_pmax_i1_q1_2023_with_gla','marketing','en_US','New customization features to boost your business','You can now add custom images, messaging, and URLs to campaigns in Google Listings &amp; Ads. Google then automatically tests multiple combinations to create the most engaging version to help boost your business. Get more sales with dynamic content – edit an existing campaign or create a new ad now.','{}','pending','woocommerce.com','2023-03-16 22:20:01',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (123,'woocommerce-wcpay-march-2023-update-needed','update','en_US','Action required: Security update for WooCommerce Payments','<strong>Your store requires a security update for WooCommerce Payments</strong>. Please update to the latest version of WooCommerce Payments immediately to address a potential vulnerability discovered on March 22. For more information on how to update, visit this WooCommerce Developer Blog Post.','{}','pending','woocommerce.com','2023-03-24 07:50:06',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (124,'tap_to_pay_iphone_q2_2023_no_wcpay','marketing','en_US','Accept in-person contactless payments on your iPhone','Tap to Pay on iPhone and WooCommerce Payments is quick, secure, and simple to set up — no extra terminals or card readers are needed. Accept contactless debit and credit cards, Apple Pay, and other NFC digital wallets in person.','{}','unactioned','woocommerce.com','2023-04-04 23:51:16',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (125,'tap_to_pay_iphone_q2_2023_with_wcpay','marketing','en_US','New: accept in-person contactless payments on your iPhone','Tap to Pay on iPhone is quick, secure, and simple to set up in WooCommerce Payments — no extra terminals or card readers are needed. Accept contactless debit and credit cards, Apple Pay, and other NFC digital wallets in person in a few short steps!','{}','pending','woocommerce.com','2023-04-03 23:06:33',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (126,'wc-admin-wcpay-denmark-Q2-2023','marketing','en_US','WooCommerce Payments is now available in Denmark!','We’ve recently released WooCommerce Payments in Denmark. You can view and manage transactions right in your WordPress dashboard while securely accepting major cards, Apple Pay, and payments in over 100 currencies.','{}','pending','woocommerce.com','2023-04-14 20:24:40',NULL,0,'plain','',0,'info');
