INSERT INTO `wpj4_wc_admin_notes` VALUES (139,'wc_admin_BNPL_WCPay_coming-soon_Q1_2023','marketing','en_US','Buy now, pay later is heading to WooCommerce Payments','Great news: full integration with Afterpay and Affirm is on its way to WooCommerce Payments! You’ll soon be able to increase your order values, sell more, and offer customers a payment option they’ll love — with no extra downloads or extensions required.','{}','pending','woocommerce.com','2023-04-26 20:44:02',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (140,'woopay-beta-existingmerchants-noaction-27APR23-test2','info','en_US','WooPay is back!','Thanks for previously trying WooPay, the express checkout feature built into WooCommerce Payments. We’re excited to announce that WooPay availability has resumed. No action is required on your part.\r\n<br /><br />\r\nYou can now continue boosting conversions by offering your customers a simple, secure way to pay with a single click.','{}','pending','woocommerce.com','2023-04-27 20:36:47',NULL,0,'plain','',0,'info');
