INSERT INTO `wpj4_wc_admin_notes` VALUES (154,'payoneer_q2_2023','marketing','en_US','Grow with the next generation of payment processing','Ready to stand out in the new global economy? Payoneer Checkout gives you the power to securely accept payments worldwide, build a checkout that customers love, and manage your store’s transactions and finances – all from the same place.','{}','pending','woocommerce.com','2023-05-14 05:48:13',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (155,'ipp_refresh_q2_2023_us_inbox_notification','marketing','en_US','Grow on the go with in-person payments','Sell your products or services on the go with the M2 card reader – a quick, synchronized, and secure way to take payments, no matter where you are. Create an order using the WooCommerce mobile app and connect your card reader to accept payments.','{}','pending','woocommerce.com','2023-05-18 21:34:48',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (156,'ipp_refresh_q2_2023_ca_inbox_notification','marketing','en_US','Grow on the go with in-person payments','Sell your products or services on the go with the WisePad 3 card reader – a quick, synchronized, and secure way to take payments, no matter where you are. Create an order using the WooCommerce mobile app and connect your card reader to accept payments.','{}','pending','woocommerce.com','2023-05-18 21:34:48',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (157,'product_management_card_sorting','survey','en_US','How do you create and edit products?','Have a say in the future of WooCommerce. Take part in a brief exercise and help us understand what information is important to you while editing products.','{}','unactioned','woocommerce.com','2023-05-18 21:34:48',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (158,'woocommerce-WCstripe-May-2023-updated-needed','update','en_US','Action required: Security update of WooCommerce Stripe plugin','<strong>Your store requires a security update for the WooCommerce Stripe plugin</strong>. Please update the WooCommerce Stripe plugin immediately to address a potential vulnerability.','{}','pending','woocommerce.com','2023-06-01 20:40:02',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (159,'woocommerce-WCReturnsWarranty-June-2023-updated-needed','update','en_US','Action required: Security update of WooCommerce Returns and Warranty Requests extension','<strong>Your store requires a security update for the Returns and Warranty Requests extension</strong>.  Please update to the latest version of the WooCommerce Returns and Warranty Requests extension immediately to address a potential vulnerability discovered on May 31.','{}','pending','woocommerce.com','2023-06-03 00:17:09',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (160,'woocommerce-WCPayments-June-2023-updated-needed','update','en_US','Action required: Security update of WooCommerce Payments','<strong>Your store requires a security update for the WooCommerce Payments plugin</strong>. Please update the WooCommerce Payments plugin immediately to address a potential vulnerability.','{}','pending','woocommerce.com','2023-06-07 07:47:01',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (161,'woocommerce-WCSubscriptions-June-2023-updated-needed','marketing','en_US','Action required: Security update of WooCommerce Subscriptions','<strong>Your store requires a security update for the WooCommerce Subscriptions plugin</strong>. Please update the WooCommerce Subscriptions plugin immediately to address a potential vulnerability.','{}','pending','woocommerce.com','2023-06-07 07:47:01',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (162,'woocommerce_hpos_1st_notification_q2_2023','marketing','en_US','High-Performance Order Storage (HPOS) is on its way','Our team is targeting August 2023 to roll out a major database upgrade that can unlock faster checkout and order creation for your customers — and lightning-quick order lookup for you. Enablement is optional and you won’t be forced to update, but read on to see why this was our most requested new feature.','{}','unactioned','woocommerce.com','2023-06-07 07:47:01',NULL,0,'plain','',0,'info');
INSERT INTO `wpj4_wc_admin_notes` VALUES (163,'woocommerce-WCOPC-June-2023-updated-needed','update','en_US','Action required: Security update of WooCommerce One Page Checkout','<strong>Your shop requires a security update to address a vulnerability in the WooCommerce One Page Checkout extension</strong>. The fix for this vulnerability was released for this extension on June 13th. Please update immediately.','{}','pending','woocommerce.com','2023-06-22 01:55:46',NULL,0,'plain','',0,'info');
