INSERT INTO `wpj4_wfissues` VALUES (1365,1745325048,1745325048,'new','knownfile',75,'42d3b8e466048315341f9bab1a6cf7d1','e2aa4fed6ce5ca5897eb8393ac0256a6','Old WordPress core file not removed during update: wp-includes/css/dist/editor/editor-styles-rtl.css','This file is in a WordPress core location but is from an older version of WordPress and not used with your current version. Hosting or permissions issues can cause these files to get left behind when WordPress is updated and they should be removed if possible.','a:5:{s:4:\"file\";s:49:\"wp-includes/css/dist/editor/editor-styles-rtl.css\";s:5:\"cType\";s:4:\"core\";s:7:\"canDiff\";b:0;s:6:\"canFix\";b:0;s:9:\"canDelete\";b:1;}');
